// The tenbri package: the API over the native addon (index.js, generated by napi-rs). Types are
// in tenbri.d.ts.
'use strict'

const { createHmac } = require('node:crypto')
const native = require('./index.js')

/** Every TENBRI_* code the SDK raises, and its error class. */
class TenbriError extends Error {
  constructor(message, { code, reason, id } = {}) {
    super(message)
    this.name = new.target.name
    this.code = code ?? new.target.code ?? 'TENBRI_INTERNAL'
    this.reason = reason ?? undefined
    this.id = id ?? undefined
  }
}
const errorClass = (name, code) => {
  const C = { [name]: class extends TenbriError {} }[name]
  C.code = code
  return C
}
const InvalidRequestError = errorClass('InvalidRequestError', 'TENBRI_INVALID_REQUEST')
const InvalidEntryError = errorClass('InvalidEntryError', 'TENBRI_INVALID_ENTRY')
const NotFoundError = errorClass('NotFoundError', 'TENBRI_NOT_FOUND')
const IdempotencyConflictError = errorClass('IdempotencyConflictError', 'TENBRI_IDEMPOTENCY_CONFLICT')
const WriteConflictError = errorClass('WriteConflictError', 'TENBRI_WRITE_CONFLICT')
const DeadlineExceededError = errorClass('DeadlineExceededError', 'TENBRI_DEADLINE_EXCEEDED')
const StoreUnavailableError = errorClass('StoreUnavailableError', 'TENBRI_STORE_UNAVAILABLE')
const NoSessionKeyError = errorClass('NoSessionKeyError', 'TENBRI_NO_SESSION_KEY')
const StreamBrokenError = errorClass('StreamBrokenError', 'TENBRI_STREAM_BROKEN')
const byCode = Object.fromEntries(
  [
    InvalidRequestError,
    InvalidEntryError,
    NotFoundError,
    IdempotencyConflictError,
    WriteConflictError,
    DeadlineExceededError,
    StoreUnavailableError,
    NoSessionKeyError,
    StreamBrokenError,
  ].map((C) => [C.code, C]),
)

/** The native addon's error (its message is JSON) as a typed error. */
function typed(e) {
  let body
  try {
    body = JSON.parse(e.message)
  } catch {
    throw e
  }
  const C = byCode[body.code] ?? TenbriError
  throw new C(body.message, body)
}
const call = (p) => p.catch(typed)

/** Raise inside a decision when your own policy refuses the action: recorded as `refused`. */
class Refused extends Error {
  constructor(message) {
    super(message)
    this.name = 'Refused'
  }
}

function principal(p) {
  if (typeof p !== 'string') return { ...p }
  const i = p.indexOf(':')
  const kind = p.slice(0, i)
  if (i > 0 && ['agent', 'person', 'service'].includes(kind)) return { kind, id: p.slice(i + 1) }
  return { kind: 'agent', id: p }
}

function draft(d) {
  const out = {}
  for (const [k, v] of Object.entries(d ?? {})) if (v !== undefined && v !== null) out[k] = v
  if (out.principal) out.principal = principal(out.principal)
  return out
}

class Run {
  #log
  #reads = []
  constructor(log, p) {
    this.#log = log
    this.principal = principal(p)
  }

  /** Records that the run read `ref` at `version`: the next decision lists it among its inputs. */
  read(ref, { version, content, digest }) {
    if (digest === undefined) {
      if (content === undefined) throw new InvalidRequestError('read() needs content or digest')
      digest = this.#log.digest(content)
    }
    this.#reads.push({ ref, version, digest })
  }

  /** A decision by the run's principal, listing the inputs read since the last one. */
  decision(options, fn) {
    const d = { principal: this.principal, ...options }
    if (this.#reads.length) {
      d.inputs = [...this.#reads, ...(options.inputs ?? [])]
      this.#reads = []
    }
    return this.#log.decision(d, fn)
  }
}

class Tenbri {
  #s
  #digestKey
  constructor(s, digestKey) {
    this.#s = s
    this.#digestKey = digestKey
  }

  /**
   * Opens the stream at `url`: a directory, file://..., s3://bucket/prefix or r2://bucket/prefix.
   */
  static async open(url, { keys, key, create, digestKey } = {}) {
    const s = await call(native.Stream.open(String(url), { keys, key, create }))
    return new Tenbri(s, digestKey)
  }

  get id() {
    return this.#s.id
  }

  get fingerprint() {
    return this.#s.fingerprint
  }

  get writable() {
    return this.#s.writable
  }

  /** The keyed digest of an input, `hmac-sha256:<hex>`, with the `digestKey` given at open. */
  digest(content) {
    if (this.#digestKey === undefined) {
      throw new InvalidRequestError('a digest needs digestKey at open, or pass digest to read()')
    }
    return 'hmac-sha256:' + createHmac('sha256', this.#digestKey).update(content).digest('hex')
  }

  async append(entry) {
    return JSON.parse(await call(this.#s.append(JSON.stringify(draft(entry)))))
  }

  async intent(d) {
    return JSON.parse(await call(this.#s.intent(JSON.stringify(draft(d)))))
  }

  async outcome(intent, s = 'ok', fields = {}) {
    const ref = JSON.stringify(typeof intent === 'string' ? { id: intent } : intent)
    return JSON.parse(await call(this.#s.outcome(ref, s, JSON.stringify(draft(fields)))))
  }

  /**
   * Records a decision around `fn`: the intent is durable before `fn` runs, then the outcome:
   * `ok`, `refused` (when `fn` throws `Refused`) or `error` (anything else it throws, rethrown).
   */
  async decision({ action, target, ...fields }, fn) {
    const intent = await this.intent({ ...fields, action: target === undefined ? { type: action } : { type: action, target } })
    let result
    try {
      result = await fn(intent)
    } catch (e) {
      await this.outcome(intent, e instanceof Refused ? 'refused' : 'error')
      throw e
    }
    await this.outcome(intent, 'ok')
    return result
  }

  /** Decisions by `principal`; inputs it reads are pinned to its next decision. */
  async run({ principal: p }, fn) {
    return fn(new Run(this, p))
  }

  async verify(key) {
    const r = JSON.parse(await call(this.#s.verify(key)))
    return {
      ok: r.broken === null && r.pinned_key !== null,
      stream: r.stream,
      entries: r.entries,
      pinnedKey: r.pinned_key,
      broken: r.broken,
      checkpoint: r.checkpoint,
    }
  }

  async query({ action, target, principal: p, subject, inputs = [], afterSeq = 0, limit } = {}) {
    const f = {
      inputs: inputs.map((i) => {
        if (typeof i !== 'string') return [...i]
        const at = i.lastIndexOf('@')
        if (at < 0) throw new InvalidRequestError(`input ${i}: expected ref@version`)
        return [i.slice(0, at), i.slice(at + 1)]
      }),
      after_seq: afterSeq,
      ...draft({ action, target, subject, limit }),
    }
    if (p !== undefined) {
      const q = principal(p)
      f.principal = `${q.kind}:${q.id}`
    }
    return JSON.parse(await call(this.#s.query(JSON.stringify(f))))
  }

  flush() {
    return call(this.#s.flush())
  }

  close() {
    return call(this.#s.close())
  }
}

/** A new entry id (ULID), for idempotent retries. */
const newId = () => native.newId()
const version = native.version()

// Shorthand only: Node finds the names to import from ESM in this literal.
module.exports = {
  DeadlineExceededError,
  IdempotencyConflictError,
  InvalidEntryError,
  InvalidRequestError,
  NoSessionKeyError,
  NotFoundError,
  Refused,
  Run,
  StoreUnavailableError,
  StreamBrokenError,
  Tenbri,
  TenbriError,
  WriteConflictError,
  newId,
  version,
}
